{"query":"query MoreTimelineItems($id: ID!, $cursor: String!) {
  node(id: $id) {
    ... on PullRequest {
      timelineItems(first: 100, after: $cursor, itemTypes: [PULL_REQUEST_COMMIT, PULL_REQUEST_REVIEW, ISSUE_COMMENT, HEAD_REF_FORCE_PUSHED_EVENT]) { ...TimelineItemsPage }
    }
  }
}

fragment PageInfoFields on PageInfo { hasNextPage endCursor }

fragment ActorFields on Actor { __typename login }

fragment TimelineItemFields on PullRequestTimelineItems {
  __typename
  ... on PullRequestCommit {
    id
    commit { oid }
  }
  ... on PullRequestReview {
    id
    author { ...ActorFields }
    state
    body
    bodyText
    submittedAt
    url
    isMinimized
    commit { oid }
  }
  ... on IssueComment {
    id
    author { ...ActorFields }
    body
    bodyText
    createdAt
    url
    isMinimized
    minimizedReason
  }
  ... on HeadRefForcePushedEvent {
    id
    actor { ...ActorFields }
    createdAt
    beforeCommit { oid }
    afterCommit { oid }
  }
}

fragment TimelineItemsPage on PullRequestTimelineItemsConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...TimelineItemFields }
